def solve_small_2(total_marbles):
    initial_state = tuple(sorted([1] * total_marbles))
    queue = [initial_state]
    visited = {initial_state}

    min_boxes = len(initial_state)

    while queue:
        current = queue.pop(0)
        min_boxes = min(min_boxes, len(current))
        if min_boxes == 1:
            break

        for i in range(len(current)):
            for j in range(i + 1, len(current)):
                n1, n2 = current[i], current[j]
                for k in range(1, min(n1, n2) + 1):
                    new_marbles = list(current)
                    new_marbles[i] -= k
                    new_marbles[j] -= k
                    new_marbles.append(2*k)

                    next_state = tuple(sorted([x for x in new_marbles if x > 0]))
                    if next_state not in visited:
                        visited.add(next_state)
                        queue.append(next_state)
    return min_boxes

for total in range(1, 16):
    print(f"Total {total}: {solve_small_2(total)}")

